-- Applied to production after wordnet-relationship-matching.sql.
-- Revalidate witness tiers after changes to the association graph.

-- 20261125013957 ascent_expand_everyday_functional_associations

-- 20261125014007 ascent_expand_verified_synonym_paths
-- Expand exact dictionary synonyms of a registered association when the anchor has one dictionary sense,
-- or where two existing vectors corroborate the synonym. No multi-hop loose association chaining.
with active as (select distinct unnest(clues) clue from ascent_game.rich_tier_boards_v7 where difficulty_grade>0),
anchors as materialized (select s.clue,s.word,s.reason,s.strength,m.synset from ascent_game.association_scores_v7 s join active a using(clue) join ascent_game.wordnet_members m on m.word=s.word where s.strength>=84 and s.reason not like 'Semantic link via %'),
candidate as (select distinct on(a.clue,n.word) a.clue,n.word,a.word anchor,a.synset,case when a.strength>=95 then 88 else 80 end strength
from anchors a join ascent_game.wordnet_members n on n.synset=a.synset and n.word<>a.word
left join ascent_game.semantic_word_vectors av on av.word=a.word left join ascent_game.semantic_word_vectors nv on nv.word=n.word
where n.word<>a.clue and length(n.word)>=3 and n.word !~ '^(thing|stuff|object|entity|part|person|individual|something|anything|everything|nothing|kind|type|act|action|event|state|process|group|set|unit|being|matter|item|do|make|get|have|take|put|go|use|work|play|run|set|way|point|case|form|one|two)$'
and (not exists(select 1 from ascent_game.wordnet_members x where x.word=a.word and x.synset<>a.synset) or (av.embedding is not null and nv.embedding is not null and 1-(av.embedding operator(extensions.<=>) nv.embedding)>=.94))
and not exists(select 1 from ascent_game.association_scores_v7 s where s.clue=a.clue and s.word=n.word)
and not exists(select 1 from ascent_game.knowledge_edges k where k.clue=a.clue and k.word=n.word)
order by a.clue,n.word,a.strength desc,a.word)
select clue,word,'synonym_of_association','Open English WordNet',anchor||' ('||synset||')',strength from candidate on conflict do nothing;
-- Keep the actual supporting association visible in the result.
do $patch$ declare d text;n text;begin
select pg_get_functiondef('ascent_game.knowledge_matches(text[],text,jsonb)'::regprocedure) into d;
n:=replace(d,'when ''synonym'' then ''Same dictionary meaning''','when ''synonym_of_association'' then ''Dictionary synonym of ''||split_part(k.evidence,'' ('',1) when ''synonym'' then ''Same dictionary meaning''');
if n=d then raise exception 'Knowledge explanation patch mismatch';end if;execute n;end;$patch$;

